import os
import pandas as pd
from scipy import stats

# locate the csv file generated by the backend
csv_path = os.path.join("..", "backend", "metrics_log.csv")

def analyze_experiment_data():
    if not os.path.exists(csv_path):
        print(f"error: could not find the metrics file at {csv_path}")
        return

    try:
        # csv parsing with built-in fallback rules to wrap messy text data strings safely
        df = pd.read_csv(csv_path, skipinitialspace=True, on_bad_lines='skip')
        
        # isolate the latency metrics for both independent testing groups
        metadata_latencies = df[df["pipeline_type"] == "metadata"]["latency_ms"]
        agentic_latencies = df[df["pipeline_type"] == "agentic"]["latency_ms"]
        
        if len(metadata_latencies) == 0 or len(agentic_latencies) == 0:
            # fallback parser calculation rule in case the text breaks traditional rows
            print("running robust fallback line parser...")
            meta_list = []
            agent_list = []
            with open(csv_path, "r", encoding="utf-8") as f:
                next(f) # skip header
                for line in f:
                    parts = line.split(",")
                    if len(parts) >= 4:
                        p_type = parts[1].strip()
                        latency = float(parts[3].strip())
                        if p_type == "metadata":
                            meta_list.append(latency)
                        elif p_type == "agentic":
                            agent_list.append(latency)
            metadata_latencies = pd.Series(meta_list)
            agentic_latencies = pd.Series(agent_list)

        # calculate standard descriptive statistical values
        mean_meta = metadata_latencies.mean()
        mean_agent = agentic_latencies.mean()
        
        print("descriptive statistics: ")
        print(f"mean metadata pipeline latency: {mean_meta:.2f} ms")
        print(f"mean agentic pipeline latency: {mean_agent:.2f} ms")
        print(f"absolute latency overhead delta: {mean_agent - mean_meta:.2f} ms\n")
        
        print("hypothesis testing (two-sample t-test): ")
        # run a two-sample t-test assuming equal variances to check our null hypothesis
        t_stat, p_value = stats.ttest_ind(metadata_latencies, agentic_latencies, equal_var=True)
        
        print(f"calculated t-statistic value: {t_stat:.4f}")
        print(f"calculated p-value parameter: {p_value:.4f}")
        
        # evaluate alpha threshold boundary for academic confidence
        alpha = 0.05
        if p_value < alpha:
            print("\nconclusion: reject the null hypothesis (h0).")
            print("the variance in processing speed between strategies is statistically significant.")
        else:
            print("\nconclusion: fail to reject the null hypothesis (h0).")
            print("the latency variance could be due to random hardware fluctuations at this sample size.")

    except Exception as e:
        print(f"an error occurred while computing metrics: {e}")

if __name__ == "__main__":
    analyze_experiment_data()